我根据自己博客的性质，进行了自己网站的Sitemap的开发。实现过程比较简单，效果还是比较令我满意的。关键是格式比较重要，还有在生成的过程中，有个在查看的时候，能够有个比较好的ui效果的设置。下面把我的Sitemap的生成代码记录如下： &lt;?phpclass Sitemap extends CController&#123; protected $webSiteTitle = &#x27;&#x27;; protected $changefreq = &#x27;&#x27;; protected $content = &#x27;&#x27;; protected $priority = &#x27;&#x27;; protected $blogItems = array(); protected $tagItems = array(); protected $categoryItems = array(); protected $items = array(); /** * 添加基本信息 * @param string $title * @param string $link * @param string $description */ public function __construct() &#123; $this-&gt;webSiteTitle = &#x27;http://&#x27;.$_SERVER[&#x27;SERVER_NAME&#x27;]; $this-&gt;changefreq = &#x27;daily&#x27;;//always hourly daily weekly monthly yearly never $this-&gt;priority = 0.5; &#125; /** * 分类 */ private function categorySitemap()&#123; $criteria = new CDbCriteria(); $criteria-&gt;condition = &#x27;category=:category&#x27;; $criteria-&gt;params = array(&#x27;:category&#x27;=&gt;&#x27;blog&#x27;); $criteria-&gt;order = &#x27;create_date DESC&#x27;; $result = Type::model()-&gt;findAll($criteria); foreach($result as $k=&gt;$v)&#123; $this-&gt;categoryItems[] = array( &#x27;url&#x27;=&gt;$this-&gt;webSiteTitle.&#x27;/category/&#x27;.urlencode($v-&gt;name), &#x27;date&#x27;=&gt;date(DATE_W3C, strtotime($v-&gt;update_date)) ); &#125; &#125; /** * 文章 */ private function blogSitemap()&#123; $criteria = new CDbCriteria(); $criteria-&gt;condition = &#x27;is_lock=0 and is_delete=0&#x27;; $criteria-&gt;select = &#x27;id, tag, update_date&#x27;; $criteria-&gt;order = &#x27;create_date DESC&#x27;; $model = Blog::model()-&gt;findAll($criteria); foreach($model as $k=&gt;$v)&#123; $this-&gt;blogItems[] = array( &#x27;url&#x27;=&gt;$this-&gt;webSiteTitle.&#x27;/blog/&#x27;.$v-&gt;id, &#x27;date&#x27;=&gt;date(DATE_W3C, strtotime($v-&gt;update_date)) ); $tagArr = preg_split(&#x27;#,|，#i&#x27;, $v-&gt;tag); if(!empty($tagArr))&#123; foreach($tagArr as $k=&gt;$v)&#123; if(!in_array($v,$this-&gt;tagItems))&#123; $this-&gt;tagItems[] = $v; &#125; &#125; &#125; &#125; //创建临时函数数组 $tmp = array(); $tmp = $this-&gt;tagItems; $this-&gt;tagItems = array(); foreach($tmp as $k=&gt;$v)&#123; $this-&gt;tagItems[] = array( &#x27;url&#x27;=&gt;$this-&gt;webSiteTitle.&#x27;/tag/&#x27;.urlencode($v), &#x27;date&#x27;=&gt;date(DATE_W3C, time()) ); &#125; unset($tmp); &#125; /** * 构建xml元素 */ public function buildSitemap() &#123; $blogitem = &#x27;&#x27;; foreach($this-&gt;blogItems as $k=&gt;$v)&#123; $blogitem .= &lt;&lt;&lt;BLOG &lt;url&gt;
 &lt;loc&gt;&#123;$v[&#x27;url&#x27;]&#125;&lt;/loc&gt;
 &lt;lastmod&gt;&#123;$v[&#x27;date&#x27;]&#125;&lt;/lastmod&gt;
 &lt;changefreq&gt;&#123;$this-&gt;changefreq&#125;&lt;/changefreq&gt;
 &lt;priority&gt;&#123;$this-&gt;priority&#125;&lt;/priority&gt;
 &lt;/url&gt;
BLOG; &#125; $categoryitem = &#x27;&#x27;; foreach($this-&gt;categoryItems as $k=&gt;$v)&#123; $categoryitem .= &lt;&lt;&lt;BLOG &lt;url&gt;
 &lt;loc&gt;&#123;$v[&#x27;url&#x27;]&#125;&lt;/loc&gt;
 &lt;lastmod&gt;&#123;$v[&#x27;date&#x27;]&#125;&lt;/lastmod&gt;
 &lt;changefreq&gt;&#123;$this-&gt;changefreq&#125;&lt;/changefreq&gt;
 &lt;priority&gt;&#123;$this-&gt;priority&#125;&lt;/priority&gt;
 &lt;/url&gt;
BLOG; &#125; $tagitem = &#x27;&#x27;; foreach($this-&gt;tagItems as $k=&gt;$v)&#123; $tagitem .= &lt;&lt;&lt;BLOG &lt;url&gt;
