SITEMAP; &#125; /** * 输出sitemap内容 */ function show() &#123; $this-&gt;blogSitemap(); $this-&gt;categorySitemap(); if (empty($this-&gt;content)) &#123; $this-&gt;buildSitemap(); &#125; return $this-&gt;content; &#125; /** * 将rss保存为文件 * @param String $fname * @return boolean */ function saveToFile($fname) &#123; $handle = fopen($fname, &#x27;wb&#x27;); if ($handle === false)&#123; return false; &#125; fwrite($handle, $this-&gt;content); fclose($handle); &#125; /** * 获取文件的内容 * @param String $fname * @return boolean */ function getFile($fname) &#123; $handle = fopen($fname, &#x27;r&#x27;); if ($handle === false)&#123; return false; &#125; while(!feof($handle))&#123; echo fgets($handle); &#125; fclose($handle); &#125;&#125;?&gt; Controller中我建立了两个action 1234567891011121314/** * sitemap列表 */public function actionSitemap()&#123; //rss创建 $obj = new Sitemap(); $this-&gt;render(&#x27;sitemap&#x27;,array(&#x27;rss&#x27;=&gt;$obj-&gt;show()));&#125;public function actionSitemapXsl()&#123; $this-&gt;render(&#x27;sitemapxsl&#x27;);&#125; View的两个文件的代码如下 sitemap.php 123456&lt;?php/* @var $this FeedController */header(&quot;Content-Type: text/xml; charset=utf-8&quot;);echo $rss;exit;?&gt; sitemapxsl.php 123456789101112131415161718192021222324252627282930313233343536373839404142434445464748495051525354555657585960616263646566676869707172737475767778798081828384858687888990919293949596979899100101102103104105106107108109110111112113114115116117118119&lt;?phpheader(&quot;Content-Type: text/xml; charset=utf-8&quot;);?&gt;&lt;?php$xml = &lt;&lt;&lt;XML&lt;?xml version=&quot;1.0&quot; encoding=&quot;UTF-8&quot;?&gt;&lt;xsl:stylesheet version=&quot;2.0&quot; xmlns:html=&quot;http://www.w3.org/TR/REC-html40&quot; xmlns:sitemap=&quot;http://www.sitemaps.org/schemas/sitemap/0.9&quot; xmlns:xsl=&quot;http://www.w3.org/1999/XSL/Transform&quot;&gt; &lt;xsl:output method=&quot;html&quot; version=&quot;1.0&quot; encoding=&quot;UTF-8&quot; indent=&quot;yes&quot;/&gt; &lt;xsl:template match=&quot;/&quot;&gt; &lt;html xmlns=&quot;http://www.w3.org/1999/xhtml&quot;&gt; &lt;head&gt; &lt;title&gt;XML Sitemap&lt;/title&gt; &lt;meta http-equiv=&quot;Content-Type&quot; content=&quot;text/html; charset=utf-8&quot; /&gt; &lt;style type=&quot;text/css&quot;&gt; body &#123; font-family:&quot;Lucida Grande&quot;,&quot;Lucida Sans Unicode&quot;,Tahoma,Verdana; font-size:13px; &#125; #intro &#123; background-color:#CFEBF7; border:1px #2580B2 solid; padding:5px 13px 5px 13px; margin:10px; &#125; #intro p &#123; line-height: 16.8667px; &#125; td &#123; font-size:11px; &#125; th &#123; text-align:left; padding-right:30px; font-size:11px; &#125; tr.high &#123; background-color:whitesmoke; &#125; #footer &#123; padding:2px; margin:10px; font-size:8pt; color:gray; &#125; #footer a &#123; color:gray; &#125; a &#123; color:black; &#125; &lt;/style&gt; &lt;/head&gt; &lt;body&gt; &lt;h1&gt;XML Sitemap&lt;/h1&gt; &lt;div id=&quot;intro&quot;&gt; &lt;p&gt; This is a XML Sitemap which is supposed to be processed by search engines like &lt;a href=&quot;http://www.google.com&quot;&gt;Google&lt;/a&gt;, &lt;a href=&quot;http://search.msn.com&quot;&gt;MSN Search&lt;/a&gt; and &lt;a href=&quot;http://www.yahoo.com&quot;&gt;YAHOO&lt;/a&gt;.&lt;br /&gt; It was generated using the Blogging-Software &lt;a href=&quot;http://gowhich.com/&quot;&gt;GoWhich&lt;/a&gt; and the &lt;a href=&quot;http://www.gowhich.com/sitemap.xml&quot; title=&quot;Google Sitemap Generator Plugin for GoWhich&quot;&gt;Google Sitemap Generator Plugin&lt;/a&gt; by &lt;a href=&quot;http://www.gowhich.com/&quot;&gt;GoWhich&lt;/a&gt;.&lt;br /&gt; You can find more information about XML sitemaps on &lt;a href=&quot;http://sitemaps.org&quot;&gt;sitemaps.org&lt;/a&gt; and Google&#x27;s &lt;a href=&quot;http://code.google.com/sm_thirdparty.html&quot;&gt;list of sitemap programs&lt;/a&gt;. &lt;/p&gt; &lt;/div&gt; &lt;div id=&quot;content&quot;&gt; &lt;table cellpadding=&quot;5&quot;&gt; &lt;tr style=&quot;border-bottom:1px black solid;&quot;&gt; &lt;th&gt;URL&lt;/th&gt; &lt;th&gt;Priority&lt;/th&gt; &lt;th&gt;Change Frequency&lt;/th&gt; &lt;th&gt;LastChange (GMT)&lt;/th&gt; &lt;/tr&gt; &lt;xsl:variable name=&quot;lower&quot; select=&quot;&#x27;abcdefghijklmnopqrstuvwxyz&#x27;&quot;/&gt; &lt;xsl:variable name=&quot;upper&quot; select=&quot;&#x27;ABCDEFGHIJKLMNOPQRSTUVWXYZ&#x27;&quot;/&gt; &lt;xsl:for-each select=&quot;sitemap:urlset/sitemap:url&quot;&gt; &lt;tr&gt; &lt;xsl:if test=&quot;position() mod 2 != 1&quot;&gt; &lt;xsl:attribute name=&quot;class&quot;&gt;high&lt;/xsl:attribute&gt; &lt;/xsl:if&gt; &lt;td&gt; &lt;xsl:variable name=&quot;itemURL&quot;&gt; &lt;xsl:value-of select=&quot;sitemap:loc&quot;/&gt; &lt;/xsl:variable&gt; &lt;a href=&quot;&#123;\$itemURL&#125;&quot;&gt; &lt;xsl:value-of select=&quot;sitemap:loc&quot;/&gt; &lt;/a&gt; &lt;/td&gt; &lt;td&gt; &lt;xsl:value-of select=&quot;concat(sitemap:priority*100,&#x27;%&#x27;)&quot;/&gt; &lt;/td&gt; &lt;td&gt; &lt;xsl:value-of select=&quot;concat(translate(substring(sitemap:changefreq, 1, 1),concat(\$lower, \$upper),concat(\$upper, \$lower)),substring(sitemap:changefreq, 2))&quot;/&gt; &lt;/td&gt; &lt;td&gt; &lt;xsl:value-of select=&quot;concat(substring(sitemap:lastmod,0,11),concat(&#x27; &#x27;, substring(sitemap:lastmod,12,5)))&quot;/&gt; &lt;/td&gt; &lt;/tr&gt; &lt;/xsl:for-each&gt; &lt;/table&gt; &lt;/div&gt; &lt;div id=&quot;footer&quot;&gt; Generated with &lt;a href=&quot;http://www.gowhich.com/sitemap.xml&quot; title=&quot;Google Sitemap Generator Plugin for GoWhich&quot;&gt;Google Sitemap Generator Plugin for GoWhich&lt;/a&gt; by &lt;a href=&quot;http://www.gowhich.com/&quot;&gt;GoWhich&lt;/a&gt;. This XSLT template is released under GPL. &lt;/div&gt; &lt;/body&gt; &lt;/html&gt; &lt;/xsl:template&gt;&lt;/xsl:stylesheet&gt;XML;echo $xml;exit;?&gt; 为了使得url看起来好看一点。 我做了一下路由设置 12&#x27;sitemap.xsl&#x27;=&gt;&#x27;site/sitemapxsl&#x27;,&#x27;sitemap.xml&#x27;=&gt;&#x27;site/sitemap&#x27;,

