在ios的开发中，日期选择器是个用的还是蛮多的一个部分，填写用户的出生日期，填写自己的计划，填写自己的约会安排，都是会有用到日期选择的地方的。 我认为这里面的关键点是设置日期的格式（datePickerMode），还有选择日期后去如何处理(这里我没有做)， 浏览一下代码吧 UIDatePickerDemoViewController.m 12345678910111213141516171819202122232425262728293031323334353637383940414243444546474849505152535455565758596061626364656667686970717273747576777879//// UIDatePickerDemoViewController.m// UIDatePickerDemo//// Created by david on 13-8-16.// Copyright (c) 2013年 WalkerFree. All rights reserved.//#import &quot;UIDatePickerDemoViewController.h&quot;@interface UIDatePickerDemoViewController ()@end@implementation UIDatePickerDemoViewController- (void)viewDidLoad&#123; [super viewDidLoad]; self.navigationController.navigationBar.tintColor = COOKBOOK_PURPLE_COLOR; self.navigationItem.rightBarButtonItem = BARBUTTON(@&quot;操作&quot;, @selector(action:)); UISegmentedControl *seg= [[UISegmentedControl alloc] initWithItems:[@&quot;Time Date DC Count&quot; componentsSeparatedByString:@&quot; &quot;]]; seg.segmentedControlStyle = UISegmentedControlStyleBar; seg.selectedSegmentIndex = 0; self.navigationItem.titleView = seg;&#125;- (void)didReceiveMemoryWarning&#123; [super didReceiveMemoryWarning]; // Dispose of any resources that can be recreated.&#125;#pragma mark - method of UIActionSheet-(void) actionSheet:(UIActionSheet *)actionSheet clickedButtonAtIndex:(NSInteger)buttonIndex&#123; UIDatePicker *datePicker = (UIDatePicker *)[actionSheet viewWithTag:101]; NSDateFormatter *formattor = [[NSDateFormatter alloc] init]; switch ([(UISegmentedControl *) self.navigationItem.titleView selectedSegmentIndex]) &#123; case 0: formattor.dateFormat = @&quot;h:mm a&quot;; break; case 1: formattor.dateFormat = @&quot;dd MMMM yy&quot;; break; case 2: formattor.dateFormat = @&quot;MM/dd/YY h:mm a&quot;; break; case 3: formattor.dateFormat = @&quot;HH:mm&quot;; break; default: break; &#125; NSString *timestamp = [formattor stringFromDate:datePicker.date]; [(UILabel *)[self.view viewWithTag:103] setText:timestamp]; &#125;#pragma mark - method of self-(void) action:(id)sender&#123; NSString *title = UIDeviceOrientationIsLandscape([UIDevice currentDevice].orientation) ? @&quot;








