UIPickerView的完美使用 基于视图的选取器 关于这个，其实在许多的项目开发中，还是有很多必要的，因为，你要实现一个图片说明，而不需要文字的话，这个就是个关键点，使用图标来做选择项。 原理其实也是很简单的，只要在-(UIView *) pickerView:(UIPickerView *)pickerView viewForRow:(NSInteger)row forComponent:(NSInteger)component reusingView:(UIView *)view 实现对每个Component中的row进行uiview的操作就好了。 12345678910111213-(UIView *) pickerView:(UIPickerView *)pickerView viewForRow:(NSInteger)row forComponent:(NSInteger)component reusingView:(UIView *)view&#123; UIImageView *imageView; imageView = view ? (UIImageView *)view : [[UIImageView alloc] initWithFrame:CGRectMake(0.0f, 0.0f, 60.0f, 60.0f)]; NSArray *names = [NSArray arrayWithObjects:@&quot;club.png&quot;, @&quot;diamond.png&quot;, @&quot;heart.png&quot;, @&quot;spade.png&quot;, nil]; imageView.image = [UIImage imageNamed:[names objectAtIndex:(row % 4)]]; CFShow((__bridge CFTypeRef)(imageView.image)); return imageView;&#125; 是不是很简单，其实UIPickerView里面已经自己的设置了这个方法，很是方便。 代码呈现如下： ViewBasedPickerViewController.m 123456789101112131415161718192021222324252627282930313233343536373839404142434445464748495051525354555657585960616263646566676869707172737475767778798081828384858687888990919293949596979899100//// ViewBasedPickerViewController.m// View based Picker//// Created by david on 13-8-16.// Copyright (c) 2013年 WalkerFree. All rights reserved.//#import &quot;ViewBasedPickerViewController.h&quot;@interface ViewBasedPickerViewController ()@end@implementation ViewBasedPickerViewController- (void)viewDidLoad&#123; [super viewDidLoad]; srandom([NSDate timeIntervalSinceReferenceDate]); self.navigationController.navigationBar.tintColor = COOKBOOK_PURPLE_COLOR; self.navigationItem.rightBarButtonItem = BARBUTTON(@&quot;操作&quot;, @selector(action:));&#125;- (void)didReceiveMemoryWarning&#123; [super didReceiveMemoryWarning]; // Dispose of any resources that can be recreated.&#125;#pragma mark - method of uipickerview-(NSInteger) numberOfComponentsInPickerView:(UIPickerView *)pickerView&#123; return 3;&#125;-(NSInteger) pickerView:(UIPickerView *)pickerView numberOfRowsInComponent:(NSInteger)component&#123; return 1000000;&#125;-(CGFloat) pickerView:(UIPickerView *)pickerView rowHeightForComponent:(NSInteger)component&#123; return 100.0f;&#125;-(UIView *) pickerView:(UIPickerView *)pickerView viewForRow:(NSInteger)row forComponent:(NSInteger)component reusingView:(UIView *)view&#123; UIImageView *imageView; imageView = view ? (UIImageView *)view : [[UIImageView alloc] initWithFrame:CGRectMake(0.0f, 0.0f, 60.0f, 60.0f)]; NSArray *names = [NSArray arrayWithObjects:@&quot;club.png&quot;, @&quot;diamond.png&quot;, @&quot;heart.png&quot;, @&quot;spade.png&quot;, nil]; imageView.image = [UIImage imageNamed:[names objectAtIndex:(row % 4)]]; CFShow((__bridge CFTypeRef)(imageView.image)); return imageView;&#125;#pragma mark - method of uiactionsheet-(void)actionSheet:(UIActionSheet *)actionSheet clickedButtonAtIndex:(NSInteger)buttonIndex&#123; UIPickerView *pickerView = (UIPickerView *)[actionSheet viewWithTag:101]; NSArray *names = [NSArray arrayWithObjects:@&quot;C&quot;,@&quot;D&quot;,@&quot;H&quot;,@&quot;S&quot;, nil]; self.title = [NSString stringWithFormat:@&quot;%@•%@•%@&quot;, [names objectAtIndex:([pickerView selectedRowInComponent:0] % 4)], [names objectAtIndex:([pickerView selectedRowInComponent:1] % 4)], [names objectAtIndex:([pickerView selectedRowInComponent:2] % 4)] ]; &#125;#pragma mark - method of self-(void) action:(id) sender&#123; NSString *title = UIDeviceOrientationIsLandscape([UIDevice currentDevice].orientation) ? @&quot;








